CREATE TABLE IF NOT EXISTS certifications (id TEXT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS certification_generations (id TEXT PRIMARY KEY, certification_id TEXT NOT NULL REFERENCES certifications(id), version TEXT NOT NULL, required_exams INTEGER NOT NULL CHECK(required_exams > 0), UNIQUE(certification_id,version));
CREATE TABLE IF NOT EXISTS certification_exams (code TEXT PRIMARY KEY, generation_id TEXT NOT NULL REFERENCES certification_generations(id), name TEXT NOT NULL, position INTEGER NOT NULL CHECK(position > 0), availability TEXT NOT NULL CHECK(availability IN ('available','upcoming','retiring','retired','unverified')), checked_on TEXT NOT NULL, source_url TEXT NOT NULL, bank_status TEXT NOT NULL DEFAULT 'unavailable' CHECK(bank_status IN ('unavailable','legacy-starter','reviewed')), objectives_verified INTEGER NOT NULL DEFAULT 0 CHECK(objectives_verified IN (0,1)), UNIQUE(generation_id,position));
CREATE TABLE IF NOT EXISTS exam_catalog_links (exam_code TEXT PRIMARY KEY REFERENCES exam_versions(code), catalog_code TEXT NOT NULL UNIQUE REFERENCES certification_exams(code), CHECK(exam_code = catalog_code));
